CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB;
CREATE TABLE projects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, description TEXT, active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE work_types (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, kind ENUM('material','labour','other') NOT NULL DEFAULT 'material', active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE units (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE unit_conversions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, from_unit_id INT UNSIGNED NOT NULL, to_unit_id INT UNSIGNED NOT NULL, factor DECIMAL(18,8) NOT NULL, UNIQUE(from_unit_id,to_unit_id), FOREIGN KEY(from_unit_id) REFERENCES units(id), FOREIGN KEY(to_unit_id) REFERENCES units(id), CHECK(factor>0 AND from_unit_id<>to_unit_id)) ENGINE=InnoDB;
CREATE TABLE items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, category_id INT UNSIGNED NOT NULL, unit_id INT UNSIGNED NOT NULL, rate_unit_id INT UNSIGNED NOT NULL, rate_basis DECIMAL(18,4) NOT NULL DEFAULT 1, default_rate DECIMAL(18,2) NOT NULL DEFAULT 0, active TINYINT NOT NULL DEFAULT 1, FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(unit_id) REFERENCES units(id), FOREIGN KEY(rate_unit_id) REFERENCES units(id), CHECK(rate_basis>0 AND default_rate>=0)) ENGINE=InnoDB;
CREATE TABLE contacts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, phone VARCHAR(50), type ENUM('Supplier','Contractor','Both') NOT NULL DEFAULT 'Supplier', notes TEXT) ENGINE=InnoDB;
CREATE TABLE expenses (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id INT UNSIGNED NOT NULL, contact_id INT UNSIGNED NULL, expense_date DATE NOT NULL, notes TEXT, status ENUM('active','cancelled') NOT NULL DEFAULT 'active', total DECIMAL(18,2) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(contact_id) REFERENCES contacts(id), INDEX(project_id,expense_date), CHECK(total>=0)) ENGINE=InnoDB;
CREATE TABLE expense_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, expense_id INT UNSIGNED NOT NULL, item_id INT UNSIGNED NOT NULL, work_type_id INT UNSIGNED NOT NULL, category_id INT UNSIGNED NOT NULL, description VARCHAR(150) NOT NULL, quantity DECIMAL(18,4) NULL, unit_id INT UNSIGNED NULL, unit_name VARCHAR(80) NULL, rate DECIMAL(18,2) NOT NULL, rate_unit_id INT UNSIGNED NULL, rate_unit_name VARCHAR(80) NULL, rate_basis DECIMAL(18,4) NOT NULL DEFAULT 1, conversion_factor DECIMAL(18,8) NOT NULL DEFAULT 1, total DECIMAL(18,2) NOT NULL, is_fixed TINYINT NOT NULL DEFAULT 0, FOREIGN KEY(expense_id) REFERENCES expenses(id), FOREIGN KEY(item_id) REFERENCES items(id), FOREIGN KEY(work_type_id) REFERENCES work_types(id), FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(unit_id) REFERENCES units(id), FOREIGN KEY(rate_unit_id) REFERENCES units(id), CHECK(total>=0 AND rate>=0 AND rate_basis>0 AND conversion_factor>0)) ENGINE=InnoDB;
CREATE TABLE contracts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id INT UNSIGNED NOT NULL, contact_id INT UNSIGNED NOT NULL, work_type_id INT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, description TEXT, contract_date DATE NOT NULL, type ENUM('fixed','quantity') NOT NULL DEFAULT 'fixed', quantity DECIMAL(18,4) NULL, unit_id INT UNSIGNED NULL, unit_name VARCHAR(80) NULL, rate DECIMAL(18,2) NULL, agreed_amount DECIMAL(18,2) NOT NULL, status ENUM('Active','Completed','Cancelled') NOT NULL DEFAULT 'Active', notes TEXT, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(contact_id) REFERENCES contacts(id), FOREIGN KEY(work_type_id) REFERENCES work_types(id), FOREIGN KEY(unit_id) REFERENCES units(id), CHECK(agreed_amount>=0), INDEX(project_id,contract_date)) ENGINE=InnoDB;
CREATE TABLE contract_work_costs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, contract_id INT UNSIGNED NOT NULL, cost_date DATE NOT NULL, amount DECIMAL(18,2) NOT NULL, notes TEXT, status ENUM('active','cancelled') NOT NULL DEFAULT 'active', FOREIGN KEY(contract_id) REFERENCES contracts(id), CHECK(amount>0)) ENGINE=InnoDB;
CREATE TABLE payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id INT UNSIGNED NOT NULL, contact_id INT UNSIGNED NULL, payment_date DATE NOT NULL, amount DECIMAL(18,2) NOT NULL, method ENUM('Cash','Bank Transfer','JazzCash','Easypaisa','Cheque','Other') NOT NULL DEFAULT 'Cash', notes TEXT, status ENUM('active','cancelled') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(contact_id) REFERENCES contacts(id), INDEX(project_id,payment_date), CHECK(amount>0)) ENGINE=InnoDB;
CREATE TABLE payment_allocations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payment_id INT UNSIGNED NOT NULL, expense_id INT UNSIGNED NULL, contract_id INT UNSIGNED NULL, amount DECIMAL(18,2) NOT NULL, FOREIGN KEY(payment_id) REFERENCES payments(id), FOREIGN KEY(expense_id) REFERENCES expenses(id), FOREIGN KEY(contract_id) REFERENCES contracts(id), CHECK(amount>0), CHECK((expense_id IS NOT NULL AND contract_id IS NULL) OR (expense_id IS NULL AND contract_id IS NOT NULL))) ENGINE=InnoDB;
CREATE TABLE attachments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, expense_id INT UNSIGNED NULL, payment_id INT UNSIGNED NULL, original_name VARCHAR(255) NOT NULL, stored_name VARCHAR(80) NOT NULL UNIQUE, mime VARCHAR(80) NOT NULL, size INT UNSIGNED NOT NULL, FOREIGN KEY(expense_id) REFERENCES expenses(id), FOREIGN KEY(payment_id) REFERENCES payments(id), CHECK((expense_id IS NULL) <> (payment_id IS NULL))) ENGINE=InnoDB;
